#include <iostream>

class Inventory {
public:
    explicit Inventory(int n) : stock_(n < 0 ? 0 : n) {}

    bool remove(int n) {
        if (n < 0 || n > stock_) return false;
        stock_ -= n;
        return true;
    }

    int stock() const { return stock_; }

private:
    int stock_{};
};

int main() {
    Inventory items{5};
    const bool ok = items.remove(2);
    std::cout << (ok ? "ok " : "rejected ") << items.stock() << std::endl;
}

